import {icon,logo} from './icons.js';
import {esc,money,signed,shortMoney,pct,niceDate,today,formatNumber,sum,avg,clamp,dateOf} from './utils.js';
import {SESSIONS,EMOTIONS,SETUPS,accountStats,tradeStats,accountLabel,stageLabel,CURRENCIES} from './data.js';
import {lineChart,equitySeries,donut,bars,calendarGrid,sparkline} from './charts.js';
import {AUTH_ENABLED} from './config.js';
import {periodRange,certificateData,certificateSVG,completedPeriodWithTrades,certificateRangeLabel} from './certificates.js';

export const NAV=[
 {title:'YOUR WORKSPACE',links:[['dashboard','Overview','grid'],['trades','Journal','journal'],['accounts','Accounts','accounts'],['analytics','Insights','chart'],['risk','Tools','calculator']]}
];
export const NAV_GROUPS={
 dashboard:[['dashboard','Overview']],
 trades:[['trades','All trades'],['calendar','Calendar'],['notes','Reflections']],
 accounts:[['accounts','Accounts'],['withdrawals','Payouts']],
 analytics:[['analytics','Analytics'],['performance','Review'],['certificates','Certificates'],['goals','Goals']],
 risk:[['risk','Risk calculator'],['settings','Settings']]
};
const pages={
 dashboard:['Overview',''],trades:['Trades',''],calendar:['Calendar',''],accounts:['Accounts',''],
 analytics:['Analytics',''],performance:['Performance review',''],certificates:['Certificates',''],
 notes:['Reflections',''],goals:['Goals',''],withdrawals:['Payouts',''],risk:['Risk calculator',''],settings:['Settings','']
};
const routeRoot=(route)=>Object.keys(NAV_GROUPS).find(key=>NAV_GROUPS[key].some(([slug])=>slug===route))||'dashboard';

const fmt=(c,v,cur='USD',d=0)=>c.w.profile.hideBalances?'••••••':money(v,cur,d);
const signfmt=(c,v,cur='USD')=>c.w.profile.hideBalances?'••••••':signed(v,cur);
const statClass=(v)=>v>=0?'positive':'negative';
const empty=(title,description,iconName='spark',button='Add your first trade',action='add-trade')=>`<div class="empty-state"><div class="empty-art">${icon(iconName,30)}</div><h3>${title}</h3><p>${description}</p><button class="btn btn-primary" data-action="${action}">${icon('plus',16)} ${button}</button></div>`;
const sectionHead=(title,subtitle='',right='')=>`<div class="section-head"><div><h2>${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div>${right}</div>`;
const status=(s)=>`<span class="status-pill status-${s}"><i></i>${({active:'Active',passed:'Target reached',breached:'Breached',Paid:'Paid',Pending:'Pending',Requested:'Requested'})[s]||s}</span>`;
const button=(label,action='add-trade',ic='plus',klass='btn-primary')=>`<button class="btn ${klass}" data-action="${action}">${icon(ic,16)}${label}</button>`;
const littleBar=(value=0,color='violet')=>`<div class="progress-track"><span class="progress-fill ${color}" style="width:${clamp(value,0,100)}%"></span></div>`;
export function shell(c,inner){
 const {w,ui}=c,route=ui.route||'dashboard',curr=pages[route]||pages.dashboard;
 const root=routeRoot(route),tabs=NAV_GROUPS[root]||[];
 const selected=w.accounts.find(a=>a.id===ui.accountId)||w.accounts[0];
 const first=(w.profile.name||'Trader').split(' ')[0];
 return `<div class="app-layout ${ui.mobileMenu?'menu-open':''} ${w.profile.compact?'compact-mode':''}">
  <aside class="sidebar glass-surface">
   <div class="sidebar-brand">${logo()}</div>
   <div class="sidebar-space">
    <nav class="side-nav">${NAV.map(g=>`<div class="nav-group"><div class="nav-label">${g.title}</div>${g.links.map(([slug,title,ic])=>`<button class="nav-link ${root===slug?'active':''}" data-action="navigate" data-route="${slug}">${icon(ic,19)}<span>${title}</span>${root===slug?'<span class="active-indicator"></span>':''}</button>`).join('')}</div>`).join('')}</nav>
   </div>
   <div class="sidebar-bottom"><button class="side-profile" data-action="navigate" data-route="settings"><span class="profile-dot">${esc(first.slice(0,1).toUpperCase())}</span><span><strong>${esc(w.profile.name)}</strong><small>${c.mode==='cloud'?'Private workspace':'Local demo'}</small></span>${icon('settings',18)}</button></div>
  </aside>
  <div class="sidebar-backdrop" data-action="toggle-menu"></div>
  <div class="workspace-main">
   <header class="topbar glass-surface"><div class="topbar-start"><button class="mobile-menu icon-button" aria-label="Open menu" data-action="toggle-menu">${icon('menu',22)}</button><div class="breadcrumb"><span>PP Journey</span>${icon('chevronRight',15)}<strong>${curr[0]}</strong></div></div>
   <div class="topbar-actions">${selected?`<div class="account-switch"><span class="switch-led"></span><select aria-label="Active account" id="top-account-select">${w.accounts.map(a=>`<option value="${esc(a.id)}" ${selected.id===a.id?'selected':''}>${esc(a.name)}</option>`).join('')}</select>${icon('chevronDown',14)}</div>`:''}<button class="icon-button privacy-toggle" data-action="toggle-privacy" aria-label="Toggle account balance visibility" title="Show / hide amounts">${icon(w.profile.hideBalances?'eyeOff':'eye',19)}</button>${button('Add trade','add-trade','plus','btn-primary header-add')}</div></header>
   <main class="app-content" id="main-content">
    ${route!=='dashboard'?`<div class="route-intro"><div class="route-heading"><div><h1>${curr[0]}</h1></div><div class="heading-actions">${route==='accounts'?button('New account','add-account','plus'):route==='withdrawals'?button('New payout','add-withdrawal','plus'):route==='goals'?button('New goal','add-goal','plus'):route==='notes'?button('New reflection','add-note','plus'):''}</div></div></div>`:''}
    ${tabs.length>1?`<nav class="context-tabs" aria-label="${esc(root)} navigation">${tabs.map(([slug,label])=>`<button data-action="navigate" data-route="${slug}" class="context-tab ${slug===route?'selected':''}">${esc(label)}</button>`).join('')}</nav>`:''}
    ${inner}
    <footer class="workspace-footer"><span>PP Trading Journey · ${new Date().getFullYear()}</span><span>Your data. Your journey.</span></footer>
   </main>
  </div></div>${ui.modal?renderModal(c):''}`;
}

export function landing(c){
 const demo=c.demo||{},a=(demo.accounts||[])[0],own=(demo.trades||[]).filter(t=>t.accountId===a?.id);
 const net=sum(own,t=>t.result-(t.fees||0));
 return `<div class="landing landing-v2">
 <header class="landing-nav glass-surface"><a href="#home" class="landing-logo" aria-label="PP Trading Journey home">${logo()}</a><div class="landing-actions"><button class="btn btn-ghost" data-action="open-auth" data-auth-tab="login">Log in</button><button class="btn btn-primary" data-action="open-auth" data-auth-tab="signup">Get started ${icon('arrowRight',16)}</button></div></header>
 <section class="landing-hero" id="home"><div class="hero-orb hero-orb-a"></div><div class="hero-orb hero-orb-b"></div>
  <div class="hero-copy"><div class="hero-badge">✦ YOUR JOURNEY. IN FOCUS.</div><h1>Trade smarter.<br/><em>Grow with clarity.</em></h1><p>One beautiful space for your trades, progress and the trader you're becoming.</p><div class="hero-buttons"><button class="btn btn-primary btn-xl" data-action="enter-demo">Explore live demo ${icon('arrowUpRight',18)}</button><button class="btn btn-white btn-xl" data-action="open-auth" data-auth-tab="signup">Create account</button></div><div class="hero-proof"><span>Built for focus, not noise.</span></div></div>
  <div class="hero-visual"><div class="hero-preview glass-surface"><div class="preview-head"><div class="preview-logo">${icon('grid',17)} My journey</div><span class="preview-live"><i></i> Demo preview</span></div><div class="preview-greeting"><p>Performance snapshot</p><h3>Clarity in every trade</h3></div><div class="preview-stats"><div><small>Net performance</small><b class="${net>=0?'positive':'negative'}">${net>=0?'+':''}${money(net,'USD')}</b></div><div><small>Win rate</small><b>${pct(tradeStats(own).winRate)}</b></div></div><div class="preview-chart"><div><strong>Equity journey</strong><span>30 days</span></div>${lineChart(equitySeries(own,30),{id:'land2',height:170,currency:'USD',compact:true})}</div><div class="preview-pills"><span>${icon('calendar',14)} Calendar</span><span>${icon('chart',14)} Analytics</span><span>${icon('award',14)} Certificates</span></div></div></div>
 </section>
 <section class="features-v2" id="features"><div class="feature-top-v2"><span class="overline">EVERYTHING IN ITS PLACE</span><h2>Less noise. More progress.</h2></div><div class="feature-cards-v2"><article class="feature-card glass-surface"><span class="feature-icon blue-icon">${icon('journal',24)}</span><h3>Effortless journaling</h3><p>The essentials first. Details when you need them.</p></article><article class="feature-card glass-surface"><span class="feature-icon green-icon">${icon('chart',24)}</span><h3>Visual performance</h3><p>Green days. Red days. A clearer picture.</p></article><article class="feature-card glass-surface"><span class="feature-icon violet-icon">${icon('award',24)}</span><h3>Your milestones</h3><p>Personal performance certificates, automatically.</p></article></div></section>
 <section class="landing-cta-v2 glass-surface"><div><span class="overline">ONE TRADE AT A TIME</span><h2>Make the journey yours.</h2></div><button class="btn btn-primary btn-xl" data-action="enter-demo">Open the workspace ${icon('arrowRight',17)}</button></section>
 <footer class="landing-footer"><div>${logo()}</div><span>© ${new Date().getFullYear()} PP Trading Journey</span></footer>
 </div>`;
}

export function authView(c){const tab=c.ui.authTab||'login';return `<div class="auth-view"><button class="auth-back" data-action="back-landing">${icon('arrowLeft',17)} Back to home</button><div class="auth-brand">${logo()}</div><div class="auth-layout"><div class="auth-story"><div class="hero-badge">${icon('spark',15)} THE JOURNEY STARTS HERE</div><h1>Your best trading<br/>days start with<br/><em>better awareness.</em></h1><p>One beautiful place for your trades, your reflections, and the progress that matters.</p><div class="auth-floating glass-surface">${icon('shield',20)}<span><strong>Private by design</strong><small>Your journal belongs to you.</small></span></div><div class="auth-orbit"></div></div><div class="auth-card glass-surface"><span class="auth-card-mark">${icon('spark',24)}</span><h2>${tab==='login'?'Welcome back.':tab==='signup'?'Start your journey.':tab==='reset'?'Choose a new password.':'Reset your password.'}</h2><p>${tab==='login'?'Pick up right where your last trading day left off.':tab==='signup'?'Create your own space to track, learn, and grow.':tab==='reset'?'Secure your account with a new password.':'We will email you a password reset link.'}</p>${!AUTH_ENABLED?`<div class="setup-alert">${icon('info',19)} <div><strong>Cloud login needs one-time setup.</strong><span>The interactive demo works now. To enable real sign-up, follow README.md and connect your own Supabase project.</span></div></div>`:''}<form id="auth-form" data-form="auth">${tab!=='reset'?`<label>Email address<input name="email" type="email" placeholder="you@example.com" required autocomplete="email"/></label>`:''}${tab!=='forgot'?`<label>Password<span class="password-field"><input name="password" type="password" minlength="6" placeholder="Enter your password" required autocomplete="${tab==='signup'||tab==='reset'?'new-password':'current-password'}"/><button type="button" data-action="toggle-password" aria-label="Show or hide password">${icon('eye',19)}</button></span></label>`:''}${tab==='login'?`<button type="button" class="forgot-link" data-action="auth-tab" data-tab="forgot">Forgot password?</button>`:''}<button class="btn btn-primary auth-submit" type="submit" ${!AUTH_ENABLED?'disabled':''}>${tab==='login'?'Log in':tab==='signup'?'Create my account':tab==='reset'?'Update password':'Send reset link'} ${icon('arrowRight',17)}</button></form><div class="auth-switch">${tab==='login'?`New here? <button data-action="auth-tab" data-tab="signup">Create an account</button>`:tab==='signup'?`Already have an account? <button data-action="auth-tab" data-tab="login">Log in</button>`:`Remembered it? <button data-action="auth-tab" data-tab="login">Log in</button>`}</div><div class="auth-or"><span>OR</span></div><button class="btn btn-demo" data-action="enter-demo">${icon('eye',17)} Explore the full interactive demo ${icon('arrowRight',16)}</button><p class="auth-footnote">Demo stores sample & personal edits in this browser. Cloud sync requires connecting Supabase.</p></div></div></div>`;}
function metricCard(c,{label,value,change='',ic='chart',tone='blue',foot='',spark=[]}){return `<div class="metric-card glass-surface"><div class="metric-top"><span>${label}</span><span class="metric-icon tone-${tone}">${icon(ic,19)}</span></div><div class="metric-value">${value}</div><div class="metric-bottom"><span class="${change.startsWith('-')?'down-pill':'up-pill'}">${change||'↗ Tracking'}</span><small>${foot}</small></div>${spark.length?sparkline(spark,tone==='green'?'#21a993':tone==='pink'?'#e0718c':'#7b81f0'):''}</div>`}
function accountsNudge(){return empty('Your trading journey starts here','Create your first trading account to unlock your dashboard, charts, and insights.','accounts','Create account','add-account')}
export function dashboard(c){
 const {w}=c,a=w.accounts.find(x=>x.id===c.ui.accountId)||w.accounts[0];
 if(!a)return accountsNudge();
 const stats=accountStats(w,a),all=stats.all,st=tradeStats(all),currency=a.currency;
 const chart=equitySeries(all,30),last7=all.filter(t=>t.date>=dateOf(-6));
 const weekly=sum(last7,t=>t.result-(t.fees||0));
 const first=esc((w.profile.name||'Trader').split(' ')[0]);
 const todayPnl=sum(all.filter(t=>t.date===today()),t=>t.result-(t.fees||0));
 const currentMonth=today().slice(0,7);
 return `<div class="dash-v2">
 <section class="dash-topline"><div><div class="eyebrow-lite">YOUR TRADING SPACE <span class="live-dot"></span></div><h1>Welcome back, ${first}<span class="hello-star">✳</span></h1><p>Here's how your journey is moving.</p></div><button class="btn btn-primary dash-quickadd" data-action="add-trade">${icon('plus',16)} New trade</button></section>
 <section class="focus-strip glass-surface"><div class="focus-decoration"></div><div class="focus-content"><span class="focus-kicker">YOUR DAILY PULSE</span><h2>Progress, one trade at a time.</h2><span class="focus-date">${niceDate(today(),{weekday:'long',month:'short',day:'numeric'})}</span></div><div class="focus-number"><small>Today's P&amp;L</small><strong class="${statClass(todayPnl)}">${signfmt(c,todayPnl,currency)}</strong><span>${all.filter(t=>t.date===today()).length} trades today</span></div></section>
 <section class="metric-grid metric-grid-v2">
 ${metricCard(c,{label:'Net P&L',value:signfmt(c,st.net,currency),change:st.net>=0?'Profitable':'Negative',ic:'trend',tone:st.net>=0?'green':'pink',foot:`${st.count} trades`,spark:chart.slice(-12).map(x=>x.value)})}
 ${metricCard(c,{label:'Win rate',value:pct(st.winRate),change:`${st.wins} wins`,ic:'target',tone:'blue',foot:`${st.losses} losses`,spark:[30,35,45,44,58,55,st.winRate]})}
 ${metricCard(c,{label:'This week',value:signfmt(c,weekly,currency),change:weekly>=0?'Green week':'Red week',ic:'calendar',tone:weekly>=0?'green':'pink',foot:`${last7.length} trades`,spark:[0,2,-1,3,-2,4,weekly]})}
 </section>
 <section class="dashboard-grid dashboard-grid-v2"><div class="glass-surface panel dashboard-chart"><div class="panel-top"><div><span class="overline">EQUITY JOURNEY</span><h3>Performance</h3></div><span class="range-pill">Last 30 days</span></div><div class="chart-topline"><strong class="${statClass(st.net)}">${signfmt(c,st.net,currency)}</strong><span>${st.count} trades</span></div>${lineChart(chart,{id:'dash-v2',currency,mask:w.profile.hideBalances})}<div class="mini-chart-legend"><span><i class="green-swatch"></i> Profit</span><span><i class="red-swatch"></i> Loss</span></div></div>
 <div class="glass-surface panel challenge-panel"><div class="panel-top"><div><span class="overline">ACTIVE ACCOUNT</span><h3>${esc(a.name)}</h3></div><span class="account-kind-icon">${icon('accounts',20)}</span></div><div class="challenge-ring">${donut(a.kind==='funded'&&stats.target?stats.progress:Math.max(0,Math.min(100,st.winRate)),'#606ff3',a.kind==='funded'&&stats.target?'Target':'Win rate')}</div><div class="account-amount"><small>${stageLabel(a)}</small><strong class="${statClass(stats.stageNet)}">${signfmt(c,stats.stageNet,currency)}</strong></div><div class="account-phase-line">${status(stats.status)}<button class="text-link" data-action="navigate" data-route="accounts">Details ${icon('arrowRight',15)}</button></div>${stats.target?`<div class="target-mini"><span>Challenge target</span><span>${pct(stats.progress,0)}</span></div>${littleBar(stats.progress)}`:''}</div></section>
 <section class="dashboard-grid secondary-grid"><div class="glass-surface panel"><div class="panel-top"><div><h3>Trading calendar</h3></div><button class="text-link" data-action="navigate" data-route="calendar">View calendar ${icon('arrowRight',15)}</button></div>${calendarGrid(all,currentMonth,{mini:true,hideValues:w.profile.hideBalances})}</div><div class="glass-surface panel recent-panel"><div class="panel-top"><div><h3>Recent trades</h3></div><button class="text-link" data-action="navigate" data-route="trades">View all ${icon('arrowRight',15)}</button></div>${all.length?`<div class="recent-list">${[...all].sort((x,y)=>y.date.localeCompare(x.date)).slice(0,4).map(t=>`<button class="recent-trade" data-action="trade-detail" data-id="${esc(t.id)}"><span class="symbol-icon">${esc((t.symbol||'TR').slice(0,2))}</span><span><strong>${esc(t.symbol||'Trade')}</strong><small>${niceDate(t.date,{month:'short',day:'numeric'})} · ${esc(t.entryType||t.setup||'Planned')}</small></span><span class="trade-result ${statClass(t.result-(t.fees||0))}">${signfmt(c,t.result-(t.fees||0),currency)}</span>${icon('chevronRight',16)}</button>`).join('')}</div>`:empty('Your journey starts here','Add your first trade.')}<button class="add-trade-link" data-action="add-trade">${icon('plus',16)} Add trade</button></div></section>
 </div>`;
}

export function tradeHistory(c){const {w,ui}=c;const a=w.accounts.find(x=>x.id===ui.accountId)||w.accounts[0];if(!a)return accountsNudge();let trades=w.trades.filter(t=>t.accountId===a.id);const query=(ui.tradeSearch||'').trim().toLowerCase();if(query)trades=trades.filter(t=>[t.symbol,t.setup,t.session,t.notes,t.emotion].some(x=>String(x||'').toLowerCase().includes(query)));
 if(ui.tradeOutcome==='wins')trades=trades.filter(t=>t.result>0);if(ui.tradeOutcome==='losses')trades=trades.filter(t=>t.result<0);if(ui.tradeOutcome==='breakEven')trades=trades.filter(t=>t.result===0);
 trades.sort((x,y)=>y.date.localeCompare(x.date)||y.createdAt?.localeCompare(x.createdAt||''));const s=tradeStats(trades);return `<div class="glass-surface panel trade-filter-panel"><div class="filter-row"><div class="search-input">${icon('search',17)}<input id="trade-search" placeholder="Search symbol, setup, notes..." value="${esc(ui.tradeSearch||'')}" aria-label="Search trade history"/><button data-action="search-trades" aria-label="Search">${icon('arrowRight',16)}</button></div><div class="filters-right"><select id="trade-outcome"><option value="all">All outcomes</option>${[['wins','Wins'],['losses','Losses'],['breakEven','Breakeven']].map(([v,l])=>`<option value="${v}" ${ui.tradeOutcome===v?'selected':''}>${l}</option>`).join('')}</select><span class="filter-counter">${trades.length} trades</span></div></div></div><div class="stat-strip glass-surface"><div><small>Total trades</small><strong>${s.count}</strong></div><div><small>Win rate</small><strong>${pct(s.winRate)}</strong></div><div><small>Total P&L</small><strong class="${statClass(s.net)}">${signfmt(c,s.net,a.currency)}</strong></div><div><small>Average trade</small><strong class="${statClass(s.average)}">${signfmt(c,s.average,a.currency)}</strong></div></div><div class="glass-surface panel table-card"><div class="panel-top"><div><h3>Trade log</h3><p>Click any trade to see its complete journal entry.</p></div>${button('New trade','add-trade')}</div>${trades.length?`<div class="responsive-table"><table><thead><tr><th>Date</th><th>Instrument</th><th>Direction</th><th>Setup</th><th>Session</th><th>R:R</th><th>Result</th><th></th></tr></thead><tbody>${trades.map(t=>`<tr data-action="trade-detail" data-id="${esc(t.id)}" tabindex="0"><td><strong>${niceDate(t.date,{month:'short',day:'numeric'})}</strong><small>${new Date(t.date+'T12:00:00').getFullYear()}</small></td><td><span class="table-symbol"><i>${esc(t.symbol.slice(0,2))}</i><strong>${esc(t.symbol)}</strong></span></td><td><span class="direction ${t.direction==='Long'?'long':'short'}">${icon(t.direction==='Long'?'arrowUpRight':'arrowDownRight',13)} ${esc(t.direction)}</span></td><td>${esc(t.setup)}</td><td>${esc(t.session)}</td><td>${Number(t.rr||0).toFixed(2)}R</td><td class="table-profit ${statClass(t.result)}">${signfmt(c,t.result-(t.fees||0),a.currency)}</td><td>${icon('chevronRight',16)}</td></tr>`).join('')}</tbody></table></div>`:empty('No matching trades','Try a different search or add a new journal entry.','journal')}</div>`;}
export function accountsPage(c){const {w}=c;const totals={funded:w.accounts.filter(a=>a.kind==='funded').length,forex:w.accounts.filter(a=>a.kind==='forex').length,indian:w.accounts.filter(a=>a.kind==='indian').length};return `<div class="account-summary"><div class="glass-surface account-intro"><span class="overline">TOTAL WORKSPACES</span><h2>${w.accounts.length.toString().padStart(2,'0')} <span>trading accounts</span></h2><p>Manage challenges and trading capital in one calm space.</p><div class="account-intro-chips"><span>${icon('shield',15)} ${totals.funded} funded</span><span>${icon('globe',15)} ${totals.forex} forex</span><span>${icon('activity',15)} ${totals.indian} Indian</span></div></div><button class="account-create glass-surface" data-action="add-account"><span>${icon('plus',28)}</span><strong>New account</strong><small>Add a challenge or live account</small></button></div>
 ${w.accounts.length?`<div class="accounts-grid">${w.accounts.map(a=>{const s=accountStats(w,a);const p=a.kind==='funded'?s.progress:clamp((s.net/(a.size||1))*100+35,2,100);const active=c.ui.accountId===a.id;return `<article class="account-card glass-surface ${active?'account-selected':''}"><div class="account-card-head"><div class="account-card-icon tone-${a.kind==='funded'?'blue':a.kind==='forex'?'green':'purple'}">${icon(a.kind==='funded'?'shield':a.kind==='forex'?'globe':'activity',22)}</div><div>${status(s.status)}<h3>${esc(a.name)}</h3><span>${accountLabel(a)} · ${stageLabel(a)}</span></div><button class="icon-button small" data-action="edit-account" data-id="${esc(a.id)}" title="Edit account">${icon('edit',17)}</button></div><div class="account-card-amount"><span>Account size</span><strong>${fmt(c,a.size,a.currency)}</strong></div><div class="account-card-stats"><div><small>${s.target?'Phase profit':'Realized P&L'}</small><b class="${statClass(s.target?s.stageNet:s.net)}">${signfmt(c,s.target?s.stageNet:s.net,a.currency)}</b></div><div><small>Win rate</small><b>${pct(s.winRate)}</b></div></div><div class="account-progress"><div><span>${s.target?'Profit target':'Trading consistency'}</span><strong>${s.target?`${pct(s.progress,0)} of ${fmt(c,s.target,a.currency)}`:`${s.all.length} trades`}</strong></div>${littleBar(s.target?s.progress:Math.min(100,s.all.length*5))}</div><div class="account-card-foot"><button class="btn btn-outline" data-action="select-account" data-id="${esc(a.id)}">${active?'Viewing account':'View dashboard'} ${icon('arrowRight',15)}</button><button class="icon-button" data-action="account-detail" data-id="${esc(a.id)}" title="Account details">${icon('more',19)}</button></div>${s.status==='passed'?`<button class="advance-account" data-action="advance-account" data-id="${esc(a.id)}">${icon('award',17)} Target achieved — advance phase ${icon('arrowRight',16)}</button>`:''}${s.status==='breached'?`<div class="breach-alert">${icon('alert',17)} Loss limit reached. New trades are locked.</div>`:''}</article>`}).join('')}</div>`:accountsNudge()}`;}
export function calendarPage(c){const a=c.w.accounts.find(x=>x.id===c.ui.accountId)||c.w.accounts[0];if(!a)return accountsNudge();const trades=c.w.trades.filter(t=>t.accountId===a.id);const m=c.ui.calendarMonth||today().slice(0,7);const monthTrades=trades.filter(t=>t.date.startsWith(m));const p=tradeStats(monthTrades);const days=new Set(monthTrades.map(t=>t.date));return `<div class="calendar-page-grid"><div class="glass-surface panel calendar-major"><div class="panel-top"><div><span class="overline">YOUR TRADING DAYS</span><h3>${new Date(m+'-01T12:00:00').toLocaleDateString('en-US',{month:'long',year:'numeric'})}</h3></div><div class="calendar-controls"><button class="icon-button" data-action="calendar-prev" aria-label="Previous month">${icon('chevronLeft',20)}</button><button class="today-button" data-action="calendar-current">Today</button><button class="icon-button" data-action="calendar-next" aria-label="Next month">${icon('chevronRight',20)}</button></div></div>${calendarGrid(trades,m,{hideValues:c.w.profile.hideBalances})}<div class="calendar-legend"><span><i class="green-swatch"></i> Green day</span><span><i class="red-swatch"></i> Red day</span><span><i class="grey-swatch"></i> No trades</span></div></div><div class="calendar-side"><div class="glass-surface panel cal-month-overview"><span class="overline">MONTHLY PERFORMANCE</span><strong class="${statClass(p.net)}">${signfmt(c,p.net,a.currency)}</strong><p>${monthTrades.length} trades across ${days.size} days</p><div class="cal-side-stats"><div><span>Win rate</span><b>${pct(p.winRate)}</b></div><div><span>Winning trades</span><b>${p.wins}</b></div><div><span>Losing trades</span><b>${p.losses}</b></div><div><span>Average result</span><b>${signfmt(c,p.average,a.currency)}</b></div></div></div><div class="glass-surface panel cal-tip"><span>${icon('spark',23)}</span><h3>Consistency over intensity.</h3><p>Every cell is a lesson. Use your calendar to notice patterns—not to chase green days.</p><button class="text-link" data-action="navigate" data-route="notes">Write a reflection ${icon('arrowRight',15)}</button></div></div></div>`;}
function groupBar(trades,key,currency,mask=false){const map=new Map();trades.forEach(t=>{const k=t[key]||'Other';map.set(k,(map.get(k)||0)+Number(t.result||0)-Number(t.fees||0))});return map.size?bars([...map].map(([label,value])=>({label,value})).sort((a,b)=>b.value-a.value),{currency,mask}):'<p class="muted">Not enough trade data.</p>'}
export function analytics(c){const a=c.w.accounts.find(x=>x.id===c.ui.accountId)||c.w.accounts[0];if(!a)return accountsNudge();const trades=c.w.trades.filter(t=>t.accountId===a.id);const st=tradeStats(trades);const data=equitySeries(trades,45);return `<section class="metric-grid metric-grid-three">${metricCard(c,{label:'Net results',value:signfmt(c,st.net,a.currency),change:`${st.count} trades`,ic:'trend',tone:'blue',foot:'All-time realized'})}${metricCard(c,{label:'Average winner',value:fmt(c,st.avgWinner,a.currency),change:`${st.wins} winning trades`,ic:'arrowUpRight',tone:'green',foot:'Per profitable trade'})}${metricCard(c,{label:'Average loser',value:fmt(c,st.avgLoser,a.currency),change:`${st.losses} losing trades`,ic:'arrowDownRight',tone:'pink',foot:'Per losing trade'})}</section><section class="glass-surface panel analytics-wide"><div class="panel-top"><div><span class="overline">YOUR GROWTH OVER TIME</span><h3>Complete equity curve</h3><p>A transparent view of your realized results.</p></div><span class="range-pill">Last 45 days</span></div>${lineChart(data,{id:'analytics',height:318,currency:a.currency,mask:c.w.profile.hideBalances})}</section><section class="analytic-grid"><div class="glass-surface panel"><div class="panel-top"><div><span class="overline">WHEN YOU TRADE</span><h3>Session performance</h3></div>${icon('clock',19)}</div>${groupBar(trades,'session',a.currency,c.w.profile.hideBalances)}</div><div class="glass-surface panel"><div class="panel-top"><div><span class="overline">WHAT YOU TRADE</span><h3>Instrument performance</h3></div>${icon('activity',19)}</div>${groupBar(trades,'symbol',a.currency,c.w.profile.hideBalances)}</div><div class="glass-surface panel"><div class="panel-top"><div><span class="overline">YOUR EXECUTION</span><h3>Setup performance</h3></div>${icon('target',19)}</div>${groupBar(trades,'setup',a.currency,c.w.profile.hideBalances)}</div><div class="glass-surface panel distribution-panel"><div class="panel-top"><div><span class="overline">YOUR WIN / LOSS MIX</span><h3>Outcome breakdown</h3></div></div><div class="distribution-center">${donut(st.winRate,'#6578ef','Win rate')}<div><div class="dist-line"><i class="green-swatch"></i><span>Winning trades</span><b>${st.wins}</b></div><div class="dist-line"><i class="red-swatch"></i><span>Losing trades</span><b>${st.losses}</b></div><div class="dist-line"><i class="grey-swatch"></i><span>Breakeven</span><b>${st.count-st.wins-st.losses}</b></div></div></div></div></section>`;}
export function performance(c){const a=c.w.accounts.find(x=>x.id===c.ui.accountId)||c.w.accounts[0];if(!a)return accountsNudge();const trades=c.w.trades.filter(t=>t.accountId===a.id);const n=trades.length;const followed=trades.filter(t=>t.followedPlan).length;const adherence=n?followed/n*100:0;const e=tradeStats(trades);const losses=trades.filter(t=>t.result<0&&t.emotion!=='Calm'&&t.emotion!=='Confident');const tops=[...trades].sort((a,b)=>b.result-a.result);return `<section class="performance-hero glass-surface"><div><span class="overline">BEYOND THE NUMBERS</span><h2>Discipline is your<br/><em>real competitive edge.</em></h2><p>Track how consistently you follow your own process—even when the result isn't what you wanted.</p></div><div class="performance-score">${donut(adherence,'#6778ee','Plan adherence')}<span>Based on ${n} trades</span></div></section><section class="metric-grid metric-grid-three">${metricCard(c,{label:'Plan adherence',value:pct(adherence,0),change:`${followed}/${n} trades`,ic:'shield',tone:'green',foot:'Followed trade plan'})}${metricCard(c,{label:'Average R:R',value:`${e.count?avg(trades,t=>t.rr).toFixed(2):'0.00'}R`,change:'Risk discipline',ic:'target',tone:'blue',foot:'Average recorded R multiple'})}${metricCard(c,{label:'Emotional losses',value:String(losses.length).padStart(2,'0'),change:'Awareness metric',ic:'brain',tone:'pink',foot:'Losses outside calm/confident state'})}</section><section class="analytic-grid"><div class="glass-surface panel"><div class="panel-top"><div><span class="overline">YOUR BEST EXECUTION</span><h3>Top performing trades</h3></div></div>${tops.length?`<div class="insight-list">${tops.slice(0,4).map(t=>`<button data-action="trade-detail" data-id="${esc(t.id)}"><span class="insight-icon">${icon('arrowUpRight',18)}</span><span><strong>${esc(t.symbol)} · ${esc(t.setup)}</strong><small>${niceDate(t.date)}</small></span><b class="${statClass(t.result)}">${signfmt(c,t.result,a.currency)}</b></button>`).join('')}</div>`:empty('No trades to review','Add some trades to see what you do best.','activity')}</div><div class="glass-surface panel"><div class="panel-top"><div><span class="overline">MINDSET MATTERS</span><h3>Emotions at entry</h3></div></div>${trades.length?`${[...new Set(trades.map(t=>t.emotion||'Neutral'))].map(e=>({emotion:e,count:trades.filter(t=>t.emotion===e).length})).sort((a,b)=>b.count-a.count).slice(0,6).map(e=>`<div class="emotion-row"><span>${esc(e.emotion)}</span>${littleBar(e.count/n*100,e.emotion==='Anxious'||e.emotion==='FOMO'?'pink':'violet')}<strong>${e.count}</strong></div>`).join('')}`:'<p class="muted">Log the emotions behind each trade to reveal patterns.</p>'}</div></section><section class="glass-surface panel review-prompt"><span class="review-prompt-icon">${icon('note',25)}</span><div><h3>Make space for reflection.</h3><p>Some of your biggest breakthroughs won't show up on a P&L chart. Write down what you learned today.</p></div><button class="btn btn-primary" data-action="add-note">Write reflection ${icon('arrowRight',16)}</button></section>`;}
export function notesPage(c){const notes=[...c.w.notes].sort((a,b)=>b.date.localeCompare(a.date));return `<div class="notes-header glass-surface"><div><span class="overline">THE OTHER SIDE OF TRADING</span><h2>Clarity comes from reflection.</h2><p>Capture the thoughts, lessons, and small wins behind your trades.</p></div><span class="notes-decoration">✦</span></div><div class="notes-grid">${notes.map(n=>`<article class="note-card glass-surface"><div class="note-top"><span>${icon('calendar',15)} ${niceDate(n.date)}</span><span class="note-mood">${esc(n.mood)}</span></div><h3>${esc(n.title)}</h3><p>${esc(n.body)}</p><div class="note-footer"><button data-action="edit-note" data-id="${esc(n.id)}">${icon('edit',15)} Edit</button><button data-action="delete-note" data-id="${esc(n.id)}">${icon('trash',15)} Delete</button></div></article>`).join('')}<button class="note-add glass-surface" data-action="add-note"><span>${icon('plus',28)}</span><strong>Write a new reflection</strong><small>How did trading feel today?</small></button></div>`;}
export function goalsPage(c){const gs=c.w.goals;return `<div class="goals-banner glass-surface"><div><span class="overline">HABITS CREATE THE OUTCOME</span><h2>Progress, not perfection.</h2><p>Set meaningful goals and celebrate the little actions that move you forward.</p></div><div class="goals-banner-icon">${icon('target',46)}</div></div><div class="goals-grid">${gs.map(g=>`<div class="goal-card glass-surface"><div class="goal-card-top"><span class="goal-flag">${icon('target',19)}</span><button class="icon-button small" data-action="delete-goal" data-id="${esc(g.id)}" title="Delete goal">${icon('trash',17)}</button></div><h3>${esc(g.title)}</h3><div class="goal-progress"><strong>${g.progress}</strong><span> / ${g.target} ${esc(g.unit||'actions')}</span></div>${littleBar(g.target?g.progress/g.target*100:0)}<div class="goal-actions"><span>${pct(clamp(g.progress/g.target*100||0,0,100),0)} complete</span><div><button class="icon-button small" data-action="goal-minus" data-id="${esc(g.id)}" aria-label="Reduce progress">−</button><button class="icon-button small" data-action="goal-plus" data-id="${esc(g.id)}" aria-label="Increase progress">${icon('plus',16)}</button></div></div></div>`).join('')}<button class="goal-add glass-surface" data-action="add-goal"><span>${icon('plus',27)}</span><strong>Add a new goal</strong><small>Keep your process moving</small></button></div>`;}
export function withdrawalsPage(c){const w=c.w;const list=[...w.withdrawals].sort((a,b)=>b.date.localeCompare(a.date));const complete=list.filter(x=>x.status==='Paid');const pending=list.filter(x=>x.status!=='Paid');const paidCurrencies=[...new Set(complete.map(x=>w.accounts.find(a=>a.id===x.accountId)?.currency||'USD'))];const paidAmount=paidCurrencies.length>1?String(complete.length)+' payouts':fmt(c,sum(complete,x=>x.amount),paidCurrencies[0]||'USD');return `<section class="metric-grid metric-grid-three">${metricCard(c,{label:'Total paid out',value:paidAmount,change:`${complete.length} completed`,ic:'withdrawal',tone:'green',foot:paidCurrencies.length>1?'Multiple currencies · no conversion':'Completed withdrawals'})}${metricCard(c,{label:'Pending requests',value:String(pending.length).padStart(2,'0'),change:'In progress',ic:'clock',tone:'blue',foot:'Across your accounts'})}${metricCard(c,{label:'All withdrawals',value:String(list.length).padStart(2,'0'),change:'Total entries',ic:'accounts',tone:'purple',foot:'Complete payout history'})}</section><div class="glass-surface panel table-card"><div class="panel-top"><div><span class="overline">YOUR MONEY, TRACKED</span><h3>Withdrawal history</h3><p>Keep a clear record of every requested payout.</p></div>${button('Record withdrawal','add-withdrawal')}</div>${list.length?`<div class="responsive-table"><table><thead><tr><th>Date</th><th>Account</th><th>Amount</th><th>Status</th><th>Note</th><th>Actions</th></tr></thead><tbody>${list.map(x=>{const a=w.accounts.find(a=>a.id===x.accountId);return `<tr><td>${niceDate(x.date)}</td><td>${esc(a?.name||'Deleted account')}</td><td class="table-profit">${fmt(c,x.amount,a?.currency||'USD')}</td><td>${status(x.status)}</td><td>${esc(x.note||'—')}</td><td><div class="table-actions"><button data-action="edit-withdrawal" data-id="${esc(x.id)}" title="Edit">${icon('edit',17)}</button><button data-action="delete-withdrawal" data-id="${esc(x.id)}" title="Delete">${icon('trash',17)}</button></div></td></tr>`}).join('')}</tbody></table></div>`:empty('No withdrawals recorded','Save each payout so your financial journey stays organized.','withdrawal','Record payout','add-withdrawal')}</div><p class="fine-print">Note: The total above assumes USD. Accounts in different currencies should be reviewed individually; no FX conversion is performed.</p>`;}
export function riskPage(c){return `<section class="risk-heading glass-surface"><span class="risk-orb">${icon('shield',38)}</span><div><span class="overline">PROTECT THE DOWNSIDE</span><h2>Plan the risk.<br/><em>Then take the trade.</em></h2><p>Calculate position size and risk/reward before entering. Discipline starts before the chart.</p></div></section><section class="risk-layout"><div class="glass-surface panel risk-form"><div class="panel-top"><div><span class="overline">POSITION SIZE CALCULATOR</span><h3>Define your parameters</h3></div></div><div class="form-grid two-col"><label>Account balance<input id="risk-balance" type="number" min="1" step="any" value="${esc(c.ui.risk.balance)}"/></label><label>Risk per trade (%)<input id="risk-percent" type="number" min="0.01" max="100" step="0.01" value="${esc(c.ui.risk.percent)}"/></label><label>Entry price<input id="risk-entry" type="number" min="0.000001" step="any" value="${esc(c.ui.risk.entry)}"/></label><label>Stop loss price<input id="risk-stop" type="number" min="0.000001" step="any" value="${esc(c.ui.risk.stop)}"/></label><label>Take profit price<input id="risk-take" type="number" min="0.000001" step="any" value="${esc(c.ui.risk.take)}"/></label><label>Contract multiplier<input id="risk-multiplier" type="number" min="0.000001" step="any" value="${esc(c.ui.risk.multiplier)}"/><small>1 for units, 100,000 for standard FX lots (quote in account currency).</small></label></div><div class="risk-advisory">${icon('info',17)} Calculations exclude spreads, slippage, conversions, fees and margin. Confirm your broker's contract specs.</div></div><div class="glass-surface panel risk-results"><div class="panel-top"><div><span class="overline">YOUR RISK BREAKDOWN</span><h3>Estimated position</h3></div></div><div id="risk-output">${riskCalculation(c.ui.risk)}</div></div></section>`;}
export function riskCalculation(r){const bal=Number(r.balance),percent=Number(r.percent),entry=Number(r.entry),stop=Number(r.stop),take=Number(r.take),mult=Number(r.multiplier);const valid=bal>0&&percent>0&&entry>0&&stop>0&&entry!==stop&&mult>0;const risk=bal*percent/100;const diff=Math.abs(entry-stop);const units=valid?risk/diff:0;const lots=units/mult;const reward=valid&&take>0?Math.abs(take-entry)*units:0;const rr=risk>0?reward/risk:0;return `<div class="risk-amount"><small>Maximum planned loss</small><strong>${money(risk||0,'USD',2)}</strong><span>Based on ${pct(percent||0,2)} of ${money(bal||0,'USD')}</span></div><div class="risk-result-grid"><div><span>Position units</span><strong>${valid?formatNumber(units,4):'—'}</strong></div><div><span>Estimated lots</span><strong>${valid?formatNumber(lots,4):'—'}</strong></div><div><span>Risk / Reward</span><strong>${valid&&take>0?`${rr.toFixed(2)}R`:'—'}</strong></div><div><span>Potential reward</span><strong>${valid&&take>0?money(reward,'USD',2):'—'}</strong></div></div>${!valid?`<div class="risk-invalid">Please enter valid values. Entry must be different from stop loss.</div>`:''}<div class="risk-visual"><span>Risk <b>${money(risk||0,'USD',2)}</b></span><div><i style="width:${valid&&take>0?Math.max(15,100/(1+rr)):50}%"></i></div><span>Reward <b>${money(reward||0,'USD',2)}</b></span></div>`;}
export function settingsPage(c){const p=c.w.profile;return `<div class="settings-layout"><div class="glass-surface panel settings-main"><div class="panel-top"><div><span class="overline">YOUR PERSONAL SPACE</span><h3>Profile & preferences</h3></div>${icon('settings',20)}</div><form data-form="profile"><label>Display name<input name="name" required maxlength="60" value="${esc(p.name)}" placeholder="Your name"/></label><div class="settings-toggles"><label class="setting-toggle"><span><strong>Hide money amounts</strong><small>Mask balances and trade values on screen.</small></span><input type="checkbox" name="hideBalances" ${p.hideBalances?'checked':''}/><i></i></label><label class="setting-toggle"><span><strong>Compact layout</strong><small>See more data on larger screens.</small></span><input type="checkbox" name="compact" ${p.compact?'checked':''}/><i></i></label></div><button type="submit" class="btn btn-primary">${icon('check',17)} Save preferences</button></form></div><div class="settings-side"><div class="glass-surface panel"><span class="overline">DATA MANAGEMENT</span><h3>Own your data.</h3><p>Download a backup or bring your journal records with you.</p><button class="settings-action" data-action="export-json">${icon('download',20)} <span><strong>Export all data</strong><small>Download a JSON backup</small></span>${icon('arrowRight',16)}</button><label class="settings-action import-label">${icon('upload',20)}<span><strong>Import a backup</strong><small>Replace current workspace data</small></span>${icon('arrowRight',16)}<input type="file" id="import-json" accept="application/json,.json" hidden/></label></div><div class="glass-surface panel"><span class="overline">ACCOUNT & SESSION</span><h3>${c.mode==='cloud'?'Cloud sync enabled':'Local demo mode'}</h3><p>${c.mode==='cloud'?`Signed in as ${esc(c.user?.email||'your account')}. Your workspace is protected by user-scoped database policies.`:'Your journal is stored in this browser only until you set up a cloud account.'}</p><div class="settings-actions-row"><button class="btn btn-outline" data-action="logout">${icon('logout',16)} ${c.mode==='cloud'?'Sign out':'Leave demo'}</button>${c.mode==='demo'?`<button class="btn btn-outline danger-outline" data-action="reset-demo">${icon('refresh',16)} Reset demo</button>`:''}</div></div></div></div>`;}
export function certificatesPage(c){
 const a=c.w.accounts.find(x=>x.id===c.ui.accountId)||c.w.accounts[0];
 if(!a)return accountsNudge();
 const periods=['weekly','monthly','yearly'];
 const label={weekly:'Weekly',monthly:'Monthly',yearly:'Yearly'};
 const cards=periods.map((type)=>{
   const r=periodRange(type);const latest=certificateData(c.w,a,type,r.start,r.end);
   const last=completedPeriodWithTrades(c.w,a,type,type==='yearly'?5:type==='monthly'?18:52);
   const d=latest.trades?latest:last||latest;
   return `<article class="certificate-card glass-surface"><div class="cert-card-head"><div><span class="overline">${label[type].toUpperCase()} MILESTONE</span><h3>${label[type]} certificate</h3></div><span class="cert-status">${d.completed?'Completed':'Live preview'}</span></div>
    <div class="certificate-art">${certificateSVG(d,{prefix:`preview-${type}-${d.start}`,masked:c.w.profile.hideBalances})}</div>
    <div class="cert-actions"><span>${certificateRangeLabel(d)}</span><button class="btn btn-primary cert-download" data-action="download-certificate" data-period="${type}" data-start="${d.start}" data-end="${d.end}" ${d.trades?'':'disabled title="Add a trade to unlock your certificate"'}>${icon('download',16)} Download PNG</button></div>
   </article>`;
 }).join('');
 const requested=c.ui.dailyCertDate||today(),daily=certificateData(c.w,a,'daily',requested,requested);
 const history=[['weekly',32],['monthly',18],['yearly',6]].flatMap(([type,n])=>Array.from({length:n},(_,i)=>{
   const r=periodRange(type,new Date(),-(i+1));return certificateData(c.w,a,type,r.start,r.end);
 })).filter(d=>d?.trades>0).sort((x,y)=>y.end.localeCompare(x.end));
 const archive=history.map(d=>`<div class="archive-entry"><span class="archive-period">${d.type}</span><span class="archive-range">${certificateRangeLabel(d)}</span><strong class="${statClass(d.net)}">${c.w.profile.hideBalances?'••••':signfmt(c,d.net,d.currency)}</strong><button class="btn btn-outline" data-action="download-certificate" data-period="${d.type}" data-start="${d.start}" data-end="${d.end}">${icon('download',15)} PNG</button></div>`).join('');
 return `<section class="cert-page-head glass-surface"><div><span class="overline">PERSONAL MILESTONES</span><h2>Every chapter counts.</h2><p>Your results, beautifully remembered.</p></div><span class="cert-head-symbol">${icon('award',32)}</span></section>
 <div class="cert-intro-row"><span>Generated automatically · Based on <strong>${esc(a.name)}</strong></span><span class="cert-dot">● Weekly &nbsp; ● Monthly &nbsp; ● Yearly</span></div>
 <div class="certificate-grid">${cards}</div>
 <section class="daily-certificate glass-surface"><div class="daily-certificate-title"><div><span class="overline">ON YOUR TERMS</span><h3>Daily certificate</h3><p>Generate one whenever you want.</p></div><div class="daily-generate-controls"><label class="visually-hidden" for="daily-cert-date">Choose day</label><input id="daily-cert-date" type="date" value="${esc(requested)}"/><button class="btn btn-outline" data-action="generate-daily-certificate">${icon('plus',15)} Generate</button></div></div>${c.ui.dailyCertificateOpen?`<div class="daily-certificate-result"><div class="certificate-art">${certificateSVG(daily,{prefix:`daily-${requested}`,masked:c.w.profile.hideBalances})}</div><div class="cert-actions"><span>${certificateRangeLabel(daily)}</span><button class="btn btn-primary" data-action="download-certificate" data-period="daily" data-start="${requested}" data-end="${requested}" ${daily.trades?'':'disabled'}>${icon('download',16)} Download PNG</button></div></div>`:''}</section>
 <details class="certificate-archive glass-surface"><summary><span>${icon('journal',18)} Past certificates</span><small>${history.length} completed reports</small>${icon('chevronDown',17)}</summary><div class="archive-list">${archive||'<p class="archive-empty">Completed reports will appear here after your first trading period ends.</p>'}</div></details>
 <p class="cert-footnote">Weekly, monthly and yearly reports update from saved trades. Completed reports appear automatically in your archive. Daily certificates are generated only when you choose.</p>`;
}

export function pageView(c){switch(c.ui.route){case 'dashboard':return dashboard(c);case 'trades':return tradeHistory(c);case 'accounts':return accountsPage(c);case 'calendar':return calendarPage(c);case 'analytics':return analytics(c);case 'performance':return performance(c);case 'certificates':return certificatesPage(c);case 'notes':return notesPage(c);case 'goals':return goalsPage(c);case 'withdrawals':return withdrawalsPage(c);case 'risk':return riskPage(c);case 'settings':return settingsPage(c);default:return dashboard(c)}}
const field=(name,label,value='',type='text',opts='')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value??'')}" ${opts}/></label>`;
const select=(name,label,options,value)=>`<label>${label}<select name="${name}">${options.map(o=>{let [v,l]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${value===v?'selected':''}>${esc(l)}</option>`}).join('')}</select></label>`;
function formAccount(c,id){const old=c.w.accounts.find(a=>a.id===id);const a=old||{name:'',broker:'',kind:'funded',plan:'two-step',size:25000,currency:'USD',profitTargetPct:8,phase2TargetPct:5,dailyLossPct:5,maxLossPct:10,cost:0};return `<div class="form-grid two-col">${field('name','Account name',a.name,'text','required maxlength="70"')}${field('broker','Broker / firm',a.broker,'text','maxlength="70"')}${select('kind','Account type',[['funded','Funded challenge'],['forex','Real Forex'],['indian','Indian market']],a.kind)}${select('currency','Currency',CURRENCIES,a.currency)}${field('size','Starting balance',a.size,'number','required min="1" step="any"')}<div class="funded-fields-inline">${select('plan','Funded plan',[['two-step','2-Step evaluation'],['one-step','1-Step evaluation'],['instant','Instant funding']],a.plan)}</div></div><div class="funded-fields" ${a.kind!=='funded'?'style="display:none"':''}><div class="form-section-title">${icon('shield',17)} Challenge rules</div><div class="form-grid two-col">${field('profitTargetPct','Phase 1 target (%)',a.profitTargetPct,'number','step="any" min="0"')}${field('phase2TargetPct','Phase 2 target (%)',a.phase2TargetPct,'number','step="any" min="0"')}${field('dailyLossPct','Max daily loss (%)',a.dailyLossPct,'number','step="any" min="0"')}${field('maxLossPct','Max total loss (%)',a.maxLossPct,'number','step="any" min="0"')}${field('cost','Purchase price',a.cost,'number','step="any" min="0"')}</div><p class="form-help">Rules are configurable. Drawdown tracking uses closed-trade P&L and does not model floating loss or firm-specific trailing rules.</p></div>${old?`<div class="form-help">Changing plan or account type after entering trades may affect historical challenge calculations. Existing phase remains unchanged.</div>`:''}`;}
function formTrade(c,id){
 const old=c.w.trades.find(t=>t.id===id);
 const active=c.w.accounts.filter(a=>accountStats(c.w,a).status==='active'||a.id===old?.accountId);
 const a=c.w.accounts.find(a=>a.id===(old?.accountId||c.ui.accountId))||active[0];
 const t=old||{date:today(),time:new Date().toTimeString().slice(0,5),symbol:'',direction:'Long',session:'New York',setup:'Other',entryType:'planned',result:'',risk:'',rr:'',fees:0,emotion:'Neutral',followedPlan:false,notes:'',entryPrice:'',exitPrice:'',stopLoss:'',takeProfit:'',lotSize:''};
 const originalTime=t.time||((t.createdAt||'').match(/T(\d{2}:\d{2})/)||[])[1]||'09:30';
 const result=Math.abs(Number(t.result||0));const outcome=(t.result<0)?'loss':'profit';
 return active.length?`<div class="quick-trade-form">
  <div class="quick-trade-intro"><span class="quick-pill">✦ QUICK ENTRY</span><span>Just the essentials.</span></div>
  ${select('accountId','Account',active.map(a=>[a.id,a.name]),a?.id)}
  <fieldset class="trade-outcome-choice"><legend>Result</legend><label class="outcome-option win"><input type="radio" name="outcome" value="profit" ${outcome==='profit'?'checked':''} required/><span>${icon('arrowUpRight',18)} Profit</span></label><label class="outcome-option lose"><input type="radio" name="outcome" value="loss" ${outcome==='loss'?'checked':''}/><span>${icon('arrowDownRight',18)} Loss</span></label></fieldset>
  <div class="form-grid two-col">${field('result','Trade P&L (before fees)',result||'','number','required step="0.01" min="0" placeholder="e.g. 150"')}${field('fees','Broker fees',t.fees||0,'number','min="0" step="0.01"')}</div>
  <div class="form-grid two-col">${field('date','Date',t.date,'date','required')}${field('time','Time',originalTime,'time','required')}</div>
  ${select('entryType','Entry type', [['planned','Planned trade'],['fomo','FOMO entry'],['limit','Limit order'],['market','Market order'],['breakout','Breakout'],['revenge','Revenge trade'],['other','Other']],t.entryType||'planned')}
  <details class="more-trade-details"><summary><span>${icon('plus',18)} More options</span><small>Optional details</small>${icon('chevronDown',18)}</summary><div class="optional-fields">
   <div class="form-grid two-col">${field('symbol','Symbol / instrument',t.symbol==='Trade'?'':t.symbol,'text','maxlength="30" placeholder="e.g. XAUUSD"')}${select('direction','Direction',['Long','Short'],t.direction)}</div>
   <div class="form-grid two-col">${select('session','Trading session',SESSIONS,t.session)}${select('setup','Strategy / setup',SETUPS,t.setup)}</div>
   <div class="form-grid two-col">${field('risk','Amount risked',t.risk,'number','min="0" step="any"')}${field('rr','Realized R',t.rr,'number','step="any"')}</div>
   <div class="form-grid two-col">${field('entryPrice','Entry price',t.entryPrice,'number','step="any"')}${field('exitPrice','Exit price',t.exitPrice,'number','step="any"')}${field('stopLoss','Stop loss',t.stopLoss,'number','step="any"')}${field('takeProfit','Take profit',t.takeProfit,'number','step="any"')}${field('lotSize','Lot size',t.lotSize,'number','step="any"')}${select('emotion','Emotion',EMOTIONS,t.emotion)}</div>
   <div class="checkbox-line"><label><input type="checkbox" name="followedPlan" ${t.followedPlan?'checked':''}/> Followed my trading plan</label></div>
   <label>Notes<textarea name="notes" rows="3" placeholder="What did you learn?">${esc(t.notes)}</textarea></label>
   <label class="upload-zone">${icon('image',22)}<span>${old?.screenshot||old?.screenshotPath?'Replace screenshot':'Add chart screenshot'}</span><small>Optional image</small><input id="trade-screenshot" type="file" accept="image/png,image/jpeg,image/webp"/></label>
  </div></details>
 </div>`:empty('No active accounts','Create an account before adding trades.','accounts','Create account','add-account');
}

function formWithdrawal(c,id){const x=c.w.withdrawals.find(w=>w.id===id)||{date:today(),amount:'',accountId:c.ui.accountId,status:'Requested',note:''};return `<div class="form-grid two-col">${select('accountId','Account',c.w.accounts.map(a=>[a.id,a.name]),x.accountId)}${field('date','Date',x.date,'date','required')}${field('amount','Amount',x.amount,'number','required min="0.01" step="any"')}${select('status','Status',['Requested','Pending','Paid'],x.status)}</div>${field('note','Note (optional)',x.note,'text','maxlength="200"')}`;}
function formNote(c,id){const n=c.w.notes.find(n=>n.id===id)||{date:today(),title:'',mood:'Focused',body:''};return `${field('date','Date',n.date,'date','required')}${field('title','Title',n.title,'text','required maxlength="110"')}${select('mood','How did today feel?',['Focused','Calm','Confident','Reflective','Anxious','Frustrated','Grateful','Motivated'],n.mood)}<label>Your reflection<textarea name="body" rows="6" required placeholder="What did you learn? What would you do differently?">${esc(n.body)}</textarea></label>`;}
function formGoal(){return `${field('title','Goal title','','text','required maxlength="100"')}<div class="form-grid two-col">${field('target','Target count',10,'number','required min="1" step="1"')}${field('unit','Unit (trades, sessions...)','sessions','text','required maxlength="30"')}</div>`}
function modalDetail(c,id){const t=c.w.trades.find(t=>t.id===id);if(!t)return '';const a=c.w.accounts.find(a=>a.id===t.accountId);return `<div class="detail-hero"><div><span class="overline">TRADE JOURNAL ENTRY</span><h2>${esc(t.symbol)}</h2><span class="detail-tags"><span class="direction ${t.direction==='Long'?'long':'short'}">${icon(t.direction==='Long'?'arrowUpRight':'arrowDownRight',15)}${esc(t.direction)}</span><span>${esc(t.entryType||t.setup||'Planned')}</span><span>${esc(t.session||'—')}</span></span></div><strong class="${statClass(t.result)}">${signfmt(c,t.result-(t.fees||0),a?.currency||'USD')}</strong></div><div class="detail-grid">${[['Date',niceDate(t.date)],['Account',a?.name||'—'],['Risk',fmt(c,t.risk,a?.currency||'USD')],['Realized R',`${Number(t.rr||0).toFixed(2)}R`],['Emotion',t.emotion],['Plan followed',t.followedPlan?'Yes':'No'],['Entry',t.entryPrice||'—'],['Exit',t.exitPrice||'—'],['Stop',t.stopLoss||'—'],['Take profit',t.takeProfit||'—']].map(([k,v])=>`<div><span>${esc(k)}</span><strong>${esc(v)}</strong></div>`).join('')}</div>${t.notes?`<div class="detail-notes"><strong>Journal reflection</strong><p>${esc(t.notes)}</p></div>`:''}${t.screenshot?`<img class="trade-shot" src="${esc(t.screenshot)}" alt="Uploaded trade screenshot"/>`:t.screenshotPath?`<div class="trade-shot-loading"><img class="private-shot trade-shot" data-path="${esc(t.screenshotPath)}" alt="Private trade chart screenshot"/><span>Loading your private screenshot...</span></div>`:''}<div class="modal-foot"><button class="btn btn-outline danger-outline" data-action="delete-trade" data-id="${esc(id)}">${icon('trash',17)} Delete</button><button class="btn btn-primary" data-action="edit-trade" data-id="${esc(id)}">${icon('edit',16)} Edit trade</button></div>`;}
function modalAccount(c,id){const a=c.w.accounts.find(a=>a.id===id);if(!a)return '';const s=accountStats(c.w,a);return `<div class="account-detail-overview"><div><span class="overline">ACCOUNT OVERVIEW</span><h2>${esc(a.name)}</h2><p>${accountLabel(a)} · ${stageLabel(a)}</p></div>${status(s.status)}</div><div class="detail-grid">${[['Starting capital',fmt(c,a.size,a.currency)],['All-time P&L',signfmt(c,s.net,a.currency)],['Stage P&L',signfmt(c,s.stageNet,a.currency)],['Trades',s.total],['Daily P&L',signfmt(c,s.dayPnL,a.currency)],['Win rate',pct(s.winRate)],['Daily loss limit',a.dailyLossPct?pct(a.dailyLossPct):'Not set'],['Total loss limit',a.maxLossPct?pct(a.maxLossPct):'Not set'],['Purchase cost',fmt(c,a.cost,a.currency)],['Profit target',s.target?fmt(c,s.target,a.currency):'Not applicable']].map(([k,v])=>`<div><span>${k}</span><strong>${v}</strong></div>`).join('')}</div>${s.status==='passed'?`<div class="modal-notice">${icon('award',20)} Profit target reached. Advance to the next phase to resume new entries.</div>`:''}${s.status==='breached'?`<div class="modal-notice warning">${icon('alert',20)} Account breached. New trade entries are locked. You can still review and edit past entries.</div>`:''}<div class="modal-foot"><button class="btn btn-outline danger-outline" data-action="delete-account" data-id="${esc(id)}">${icon('trash',16)} Delete</button><button class="btn btn-outline" data-action="edit-account" data-id="${esc(id)}">${icon('edit',16)} Edit</button>${s.status==='passed'?`<button class="btn btn-primary" data-action="advance-account" data-id="${esc(id)}">${icon('award',16)} Advance phase</button>`:''}</div>`}
function modalDay(c,date){const a=c.w.accounts.find(x=>x.id===c.ui.accountId)||c.w.accounts[0];const day=c.w.trades.filter(t=>t.accountId===a?.id&&t.date===date);const v=sum(day,t=>t.result-(t.fees||0));return `<div class="day-detail"><span class="overline">TRADING DAY</span><h2>${niceDate(date,{weekday:'long',month:'long',day:'numeric'})}</h2><div class="day-total ${statClass(v)}">${signfmt(c,v,a?.currency||'USD')}</div><p>${day.length} recorded trade${day.length===1?'':'s'}</p></div>${day.map(t=>`<button class="day-trade" data-action="trade-detail" data-id="${esc(t.id)}"><span><strong>${esc(t.symbol)}</strong><small>${esc(t.direction)} · ${esc(t.setup)}</small></span><b class="${statClass(t.result)}">${signfmt(c,t.result-(t.fees||0),a?.currency||'USD')}</b>${icon('chevronRight',16)}</button>`).join('')}${!day.length?`<p class="muted">A quiet day on the calendar. Add a trade or journal your thoughts.</p>`:''}<div class="modal-foot"><button class="btn btn-outline" data-action="add-note">${icon('note',16)} Journal the day</button><button class="btn btn-primary" data-action="add-trade">${icon('plus',16)} Add trade</button></div>`;}
export function renderModal(c){const m=c.ui.modal;if(!m)return '';const types={trade:['New trade','A clear record in seconds.','trade'],account:['New account','Give your account a name and define its rules.','account'],withdrawal:['Record withdrawal','Track your payout and cash flow.','withdrawal'],note:['Daily reflection','Capture what matters beyond the chart.','note'],goal:['New habit goal','Make progress measurable.','goal']};
 const formType=m.type.replace('edit-','');const edit=m.type.startsWith('edit-');const detail=m.type==='trade-detail'||m.type==='account-detail'||m.type==='day-detail';const title=m.type==='trade-detail'?'Trade details':m.type==='account-detail'?'Account overview':m.type==='day-detail'?'Day overview':edit?`Edit ${formType}`:types[formType]?.[0]||'Details';const subtitle=detail?'A closer look at your journey.':types[formType]?.[1]||'';let body='';if(m.type==='trade-detail')body=modalDetail(c,m.id);else if(m.type==='account-detail')body=modalAccount(c,m.id);else if(m.type==='day-detail')body=modalDay(c,m.date);else if(formType==='trade')body=formTrade(c,edit?m.id:null);else if(formType==='account')body=formAccount(c,edit?m.id:null);else if(formType==='withdrawal')body=formWithdrawal(c,edit?m.id:null);else if(formType==='note')body=formNote(c,edit?m.id:null);else if(formType==='goal')body=formGoal();return `<div class="modal-overlay" data-action="close-modal"><div class="modal-dialog glass-surface ${formType==='trade'||formType==='account'?'modal-wide':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-header"><div><span class="overline">PP TRADING JOURNEY</span><h2>${esc(title)}</h2><p>${esc(subtitle)}</p></div><button class="icon-button" data-action="close-modal" aria-label="Close dialog">${icon('x',20)}</button></div>${detail?`<div class="modal-body">${body}</div>`:`<form data-form="${formType}" data-id="${esc(edit?m.id:'')}" class="modal-form"><div class="modal-body">${body}</div><div class="modal-foot"><button type="button" class="btn btn-outline" data-action="close-modal">Cancel</button><button type="submit" class="btn btn-primary">${icon('check',16)} ${edit?'Save changes':formType==='trade'?'Save trade':formType==='account'?'Create account':formType==='goal'?'Create goal':'Save'}</button></div></form>`}</div></div>`;}
